import type {MessageChunk, SendMessageParams} from '../types/ai.js';

// Shared by the provider suites, which all drive the same AIProvider interface.
/** Drains an AIProvider stream so a test can assert on the chunks as a value. */
export async function collectChunks(stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) {
    chunks.push(chunk);
  }
  return chunks;
}

/** One user turn with a fixed system prompt - the smallest valid request. */
export function userMessage(content: string): SendMessageParams {
  return {
    messages: [{role: 'user', content}],
    systemPrompt: 'You are helpful.',
  };
}
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';

export interface MockConfig {
  type: 'mock';
  structuredResponses?: Map<string, unknown>;
}

export function createMockProvider(config?: MockConfig): AIProvider {
  const structuredResponses = config?.structuredResponses ?? new Map<string, unknown>();

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : 'Hello';

      const response = `Mock response to: "${userText}"`;

      for (const word of response.split(' ')) {
        yield {type: 'text', text: word + ' '};
      }

      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}};
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      const lastMessage = params.messages[params.messages.length - 1];
      const userText = typeof lastMessage?.content === 'string' ? lastMessage.content : '';

      const preconfigured = structuredResponses.get(userText);
      if (preconfigured !== undefined) return preconfigured as T;

      return buildDefaultResponse(params.responseSchema) as T;
    },
  };
}

// Factories, not values: `array` must hand back a fresh [] to each caller.
const SCALAR_DEFAULTS: Record<string, () => unknown> = {
  array: () => [],
  string: () => '',
  number: () => 0,
  boolean: () => false,
};

function buildDefaultResponse(schema: {type: string; properties?: Record<string, {type: string}>}): unknown {
  if (schema.type === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, prop] of Object.entries(schema.properties ?? {})) {
      result[key] = buildDefaultResponse(prop);
    }
    return result;
  }

  const scalar = SCALAR_DEFAULTS[schema.type];
  return scalar ? scalar() : null;
}
import {createMockProvider} from './mockProvider.js';
import {collectChunks, userMessage} from '../providerTestSupport.js';
import type {AIProvider, SendMessageParams, ResponseSchema} from '../../types/ai.js';

describe('createMockProvider', () => {
  describe('sendMessage', () => {
    it('streams word-by-word response echoing user input', async () => {
      const provider = createMockProvider();
      const chunks = await collectChunks(provider.sendMessage(userMessage('hello world')));

      const textChunks = chunks.filter(c => c.type === 'text');
      const fullText = textChunks.map(c => (c.type === 'text' ? c.text : '')).join('');
      expect(fullText).toContain('hello world');
    });

    it('ends with stop chunk containing usage metadata', async () => {
      const provider = createMockProvider();
      const chunks = await collectChunks(provider.sendMessage(userMessage('test')));

      const stopChunk = chunks.find(c => c.type === 'stop');
      expect(stopChunk).toEqual({
        type: 'stop',
        stopReason: 'end_turn',
        usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30},
      });
    });

    it('handles non-string content in last message', async () => {
      const provider = createMockProvider();
      const params: SendMessageParams = {
        messages: [{role: 'assistant', content: [{type: 'tool_use', toolUseId: '1', name: 'test', input: {}}]}],
        systemPrompt: 'test',
      };
      const chunks = await collectChunks(provider.sendMessage(params));
      const fullText = chunks
        .filter(c => c.type === 'text')
        .map(c => (c.type === 'text' ? c.text : ''))
        .join('');
      expect(fullText).toContain('Hello');
    });
  });

  describe('generateStructured', () => {
    const objectSchema: ResponseSchema = {
      type: 'object',
      properties: {
        name: {type: 'string'},
        score: {type: 'number'},
        active: {type: 'boolean'},
      },
      required: ['name', 'score'],
    };

    type Evaluation = {name: string; score: number; active: boolean};
    const evaluate = (provider: AIProvider): Promise<Evaluation> =>
      provider.generateStructured<Evaluation>({
        messages: [{role: 'user', content: 'evaluate this'}],
        systemPrompt: 'test',
        responseSchema: objectSchema,
      });

    it('returns default values matching schema shape', async () => {
      const result = await evaluate(createMockProvider());

      expect(result).toEqual({name: '', score: 0, active: false});
    });

    it('returns preconfigured response when user text matches', async () => {
      const expected = {name: 'test', score: 95, active: true};
      const result = await evaluate(
        createMockProvider({type: 'mock', structuredResponses: new Map([['evaluate this', expected]])})
      );

      expect(result).toEqual(expected);
    });

    it('returns empty array for array schema', async () => {
      const provider = createMockProvider();
      const result = await provider.generateStructured<string[]>({
        messages: [{role: 'user', content: 'list items'}],
        systemPrompt: 'test',
        responseSchema: {type: 'array', items: {type: 'string'}},
      });

      expect(result).toEqual([]);
    });

    it('gives each caller its own array, so one mutating it cannot affect another', async () => {
      const provider = createMockProvider();
      const arraySchema: ResponseSchema = {type: 'object', properties: {items: {type: 'array'}}};
      const ask = () =>
        provider.generateStructured<{items: string[]}>({
          messages: [{role: 'user', content: 'x'}],
          systemPrompt: 'test',
          responseSchema: arraySchema,
        });

      const [first, second] = await Promise.all([ask(), ask()]);
      first.items.push('mutated');

      expect(second.items).toEqual([]);
    });

    it('falls back to default when no preconfigured response matches', async () => {
      const provider = createMockProvider({
        type: 'mock',
        structuredResponses: new Map([['other query', {result: true}]]),
      });

      const result = await provider.generateStructured<{name: string}>({
        messages: [{role: 'user', content: 'unmatched query'}],
        systemPrompt: 'test',
        responseSchema: {type: 'object', properties: {name: {type: 'string'}}},
      });

      expect(result).toEqual({name: ''});
    });
  });
});

import net from 'node:net';
import request from 'supertest';
import {createHalEngine} from './config.js';
import {log, setLogger} from './shared/logger.js';
import type {Logger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {WsAuthenticator} from './types/auth.js';
import {recordingSessionStore} from './infrastructure/writeSignalTestSupport.js';

// Both options below are declared on HalEngineConfig and were dropped at the forwarding site.

const base = {
  provider: {type: 'mock' as const},
  prompt: {identity: 'test'},
  auth: {ws: (async () => null) as unknown as WsAuthenticator},
};

describe('createHalEngine forwarding', () => {
  it('forwards an orchestrator hook, so one passed through the config actually fires', async () => {
    const seen: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {hooks: {beforeSession: async () => void seen.push('beforeSession')}},
    });
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(seen).toEqual(['beforeSession']);
  });

  it('forwards transport.port, so the server listens where the config said', async () => {
    const engine = createHalEngine({...base, transport: {port: 0}});

    await engine.start();
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheConfig: port !== 8086, real: port > 0}).toEqual({usedTheConfig: true, real: true});
  });

  it('lets an explicit start(port) win over the configured one', async () => {
    const engine = createHalEngine({...base, transport: {port: 8099}});

    await engine.start(0);
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheArgument: port !== 8099, real: port > 0}).toEqual({usedTheArgument: true, real: true});
  });
});

// The option was declared on HalEngineConfig and read by nothing, so a supplied logger received no lines.
describe('createHalEngine logger forwarding', () => {
  afterEach(() => {
    setLogger();
  });

  it("delivers the package's own log lines to a supplied logger", async () => {
    const lines: {category: string; message: string}[] = [];
    const collect = (category: string, message: string) => void lines.push({category, message});
    const logger: Logger = {debug: collect, info: collect, warn: collect, error: collect};

    const engine = createHalEngine({...base, logger, transport: {port: 0}});
    await engine.start();
    await engine.stop();

    expect(lines).toContainEqual({category: 'server', message: 'HAL Engine started'});
  });

  // Asserts on a line logged AFTER construction: nothing logs during it, so an emptiness check cannot fail.
  it('leaves an already-supplied logger in place when the config names none', async () => {
    const lines: string[] = [];
    setLogger({
      debug: (_c: string, m: string) => void lines.push(m),
      info: (_c: string, m: string) => void lines.push(m),
      warn: (_c: string, m: string) => void lines.push(m),
      error: (_c: string, m: string) => void lines.push(m),
    });

    createHalEngine({...base});
    log.info('test', 'after construction');

    expect(lines).toEqual(['after construction']);
  });
});

describe('createHalEngine orchestrator hooks reach the orchestrator', () => {
  it('processes a message when the config declares no orchestrator key at all', async () => {
    const engine = createHalEngine({...base});
    const session: ChatSession = {
      sessionId: 's-noorch',
      userId: 'u1',
      entries: [{role: 'user', content: 'ping', timestamp: ''}],
    };

    const reply = await engine.orchestrator.processMessage(session);

    expect(reply).toContain('ping');
  });

  it('hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it', async () => {
    let received = 'never called';
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeModelResponse: async (_session, systemPrompt) => {
            received = systemPrompt;
            return systemPrompt;
          },
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-prompt',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(received).toBe('test');
  });

  it('fires the lifecycle hooks in documented order for a session that completes without error', async () => {
    const order: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeSession: async () => void order.push('beforeSession'),
          beforeUserInput: async (_session, message) => {
            order.push('beforeUserInput');
            return message;
          },
          afterUserInput: async () => void order.push('afterUserInput'),
          beforeModelResponse: async (_session, systemPrompt) => {
            order.push('beforeModelResponse');
            return systemPrompt;
          },
          afterModelResponse: async () => void order.push('afterModelResponse'),
          afterSession: async () => void order.push('afterSession'),
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-order',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(order).toEqual([
      'beforeSession',
      'beforeUserInput',
      'afterUserInput',
      'beforeModelResponse',
      'afterModelResponse',
      'afterSession',
    ]);
  });
});

// An unavailable port is a condition a consumer can handle, but only if start() lets them see it.
describe('createHalEngine on a port it cannot bind', () => {
  it('rejects instead of taking the process down with an unhandled error event', async () => {
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const engine = createHalEngine({...base, transport: {port: taken}});

    await expect(engine.start()).rejects.toMatchObject({code: 'EADDRINUSE'});

    await new Promise<void>(resolve => blocker.close(() => resolve()));
  });
});

// transport.additionalRoutes and transport.rootRoutes were declared but never forwarded to createApp.
describe('createHalEngine transport extension forwarding', () => {
  it('forwards transport.additionalRoutes to createApp so the route mounts under basePath', async () => {
    const engine = createHalEngine({
      ...base,
      transport: {
        additionalRoutes: (r: import('express').Router) => r.get('/ping', (_req, res) => res.json({ok: true})),
      },
    });

    const response = await request(engine.app).get('/hal/ping');

    expect({status: response.status, body: response.body}).toEqual({status: 200, body: {ok: true}});
  });
});

// The store was declared on HalEngineConfig and reached the transport, but never the orchestrator.
describe('createHalEngine session store forwarding', () => {
  it('forwards the session store, so its write signal reaches the orchestrator', async () => {
    const saved: string[] = [];
    const session = recordingSessionStore(written => void saved.push(written.sessionId));
    const engine = createHalEngine({...base, session});

    await engine.orchestrator.processMessage(session.create('s1', 'u1') as ChatSession);

    expect(saved).toEqual(['s1']);
  });
});

